compile.workshop:
variables {
    global:
        0: timer
        1: total
        2: scores
    player:
        0: points
        1: rank
}

subroutines {
    0: resetStats
}

rule ("Initialize global variables") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(timer, 10);
        Set Global Variable(scores, Array(10, 20, 30));
    }
}

rule ("Initialize player variables") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Set Player Variable(Event Player, points, 5);
    }
}

rule ("update player") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    conditions {
        (Event Player).points > 0;
        Global.total == 0;
        Array Contains(Global.scores, 20) == True;
        Global.timer != 0;
    }
    actions {
        Modify Global Variable(timer, Add, 1);
        Set Global Variable(total, Add(Multiply(Global.timer, 2), Value In Array(Global.scores, 1)));
        Set Global Variable At Index(scores, 0, 99);
        Modify Global Variable At Index(scores, 2, Add, 5);
        Set Player Variable(Event Player, points, Subtract(Global.total, 10));
        Modify Player Variable(Event Player, points, Multiply, 2);
        Modify Player Variable(Event Player, points, Divide, 2);
        Modify Player Variable(Event Player, points, Modulo, 50);
        Set Player Variable(Event Player, rank, 1);
        Create HUD Text(All Players(All Teams), Custom String("Player points: {0}", (Event Player).points), Custom String("                                                                                                                             {0}", Custom String("                                             ")), Null, Left, -9999, Color(Orange), Null, Null, Visible To and String, Default Visibility);
        Create HUD Text(All Players(All Teams), Null, Custom String("νẹƈṭ(1, 2, 3) = {0}                                                                                                          {1}", Vector(1, 2, 3), Custom String("                                                                ")), Null, Left, -9999, Null, Color(White), Null, Visible To Sort Order String and Color, Default Visibility);
        Call Subroutine(resetStats);
    }
}

